refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.5.0

     Ora viene lanciato un ValueError se
     connection_string contiene byte nulli.




    8.1.0

     Ora restituisce un'istanza di PgSql\Connection;
     in precedenza, veniva restituita una &resource;.

  &reftitle.examples;



    Uso di pg_connect


<?php
$dbconn = pg_connect("dbname=mary");
//connessione a un database chiamato "mary"

$dbconn2 = pg_connect("host=localhost port=5432 dbname=mary");
// connessione a un database chiamato "mary" su "localhost" alla porta "5432"

$dbconn3 = pg_connect("host=sheep port=5432 dbname=mary user=lamb password=foo");
//connessione a un database chiamato "mary" sull'host "sheep" con nome utente e password

$conn_string = "host=sheep port=5432 dbname=test user=lamb password=bar";
$dbconn4 = pg_connect($conn_string);
//connessione a un database chiamato "test" sull'host "sheep" con nome utente e password

$dbconn5 = pg_connect("host=localhost options='--client_encoding=UTF8'");
//connessione a un database su "localhost" e impostazione del parametro della riga di comando che indica che la codifica è UTF-8
?>
